INSERT INTO `survey_questions` VALUES (1,'Bạn hài lòng như thế nào với dịch vụ tư vấn chọn vợt?','SINGLE_CHOICE',1,0,1,NULL),(2,'Hôm nay bạn đã mua sản phẩm hoặc sử dụng dịch vụ nào tại shop?','MULTI_CHOICE',1,1,2,'{\"key\": \"purchases\", \"section\": \"Phần 1: Phân loại khách hàng & Nhu cầu\"}'),(3,'Phong cách hoặc tần suất chơi cầu lông hiện tại của bạn là gì?','SINGLE_CHOICE',1,2,2,'{\"key\": \"playing_frequency\", \"section\": \"Phần 1: Phân loại khách hàng & Nhu cầu\"}'),(4,'Nhìn chung, bạn hài lòng như thế nào với trải nghiệm tại shop hôm nay?','RATING',1,3,2,'{\"key\": \"overall_satisfaction\", \"section\": \"Phần 2: Đánh giá Chất lượng Sản phẩm & Dịch vụ\", \"rating_max\": 5, \"rating_min\": 1}'),(5,'Bạn đánh giá chi tiết các yếu tố sau của shop ở mức độ nào?','MATRIX',1,4,2,'{\"key\": \"service_criteria\", \"section\": \"Phần 2: Đánh giá Chất lượng Sản phẩm & Dịch vụ\"}'),(6,'Điều gì làm bạn ưng ý nhất khi mua đồ tại shop?','MULTI_CHOICE',1,5,2,'{\"key\": \"highlights\", \"section\": \"Phần 2: Đánh giá Chất lượng Sản phẩm & Dịch vụ\", \"max_selections\": 3}'),(7,'Bạn mong muốn shop nhập thêm nhiều mẫu mới của thương hiệu nào trong thời gian tới?','MULTI_CHOICE',1,6,2,'{\"key\": \"future_brands\", \"section\": \"Phần 3: Định hướng Sản phẩm & Góp ý mở\", \"other_option_id\": 25}'),(8,'Bạn có sẵn sàng giới thiệu shop cho đồng đội hoặc hội nhóm đánh cầu của mình không?','RATING',1,7,2,'{\"key\": \"recommendation\", \"section\": \"Phần 3: Định hướng Sản phẩm & Góp ý mở\", \"rating_max\": 10, \"rating_min\": 1}'),(9,'Bạn có góp ý gì thêm để shop cải thiện dịch vụ phục vụ anh em lông thủ tốt hơn không?','TEXT',0,8,2,'{\"key\": \"suggestions\", \"section\": \"Phần 3: Định hướng Sản phẩm & Góp ý mở\", \"placeholder\": \"Ví dụ: Cần đan vợt lấy liền nhanh hơn, nhập thêm mẫu giày size lớn, cải thiện khâu đóng gói...\"}'),(10,'Hôm nay bạn đã mua sản phẩm hoặc sử dụng dịch vụ nào tại shop?','MULTI_CHOICE',1,1,3,'{\"key\": \"purchases\", \"section\": \"Phần 1: Phân loại 