INSERT INTO `surveys` VALUES (1,'Khảo sát trải nghiệm tư vấn và đan vợt tại cửa hàng','Đánh giá dịch vụ tư vấn chọn vợt, độ chính xác khi căng cước và chăm sóc sau bán hàng.',NULL,NULL,'ACTIVE','2026-10-16 08:20:14','2026-11-01 12:13:54',1,NULL,'SATISFACTION',NULL),(2,'[DỮ LIỆU THỬ] Trải nghiệm mua sắm – đợt 1 (SQL)','Dữ liệu thử cho báo cáo – có thể xóa bằng --clear.','2026-04-25 08:00:00','2026-12-31 23:59:00','ACTIVE','2026-04-25 08:00:00','2026-11-01 12:13:54',1,'BADMINTON_SHOP_EXPERIENCE_V1','SATISFACTION','{}'),(3,'[DỮ LIỆU THỬ] Trải nghiệm mua sắm – đợt 2 (SQL)','Dữ liệu thử cho báo cáo – có thể xóa bằng --clear.','2026-08-20 08:00:00','2026-12-31 23:59:00','ACTIVE','2026-08-20 08:00:00','2026-11-01 12:13:54',1,'BADMINTON_SHOP_EXPERIENCE_V1','SATISFACTION','{}'),(4,'TEST','dsadas','2026-10-31 17:00:00','2026-11-02 16:59:59','DRAFT','2026-11-01 04:33:23','2026-11-01 12:13:54',44,NULL,'NEW_PRODUCT','{\"audience\": \"all\", \"age_groups\": [], \"preferences\": [], \"customer_ids\": [], \"playing_levels\": []}'),(5,'[DỮ LIỆU THỬ] Thăm dò dòng vợt thiên công và giày giảm chấn Quý 4/2026','Khảo sát khách hàng cửa hàng cầu lông: Thăm dò dòng vợt thiên công và giày giảm chấn Quý 4/2026. Ý kiến giúp shop lựa chọn sản phẩm và cải thiện dịch vụ.','2026-10-01 08:00:00','2026-12-31 23:59:00','ACTIVE','2026-10-01 08:00:00','2026-11-01 12:13:54',1,NULL,'NEW_PRODUCT','{}'),(6,'[DỮ LIỆU THỬ] Nhu cầu ống cầu, phụ kiện và chu kỳ đan lại cước','Khảo sát khách hàng cửa hàng cầu lông: Nhu cầu ống cầu, phụ kiện và chu kỳ đan lại cước. Ý kiến giúp shop lựa chọn sản phẩm và cải thiện dịch vụ.','2026-10-01 08:00:00','2026-12-31 23:59:00','ACTIVE','2026-10-01 08:00:00','2026-11-01 12:13:54',1,NULL,'SHOPPING_NEEDS','{}'),(7,'[DỮ LIỆU THỬ] Góp ý giải cầu lông giao lưu và ưu đãi thành viên','Khảo sát khách hàng cửa hàng cầu lông: Góp ý giải cầu lông giao lưu và ưu đãi thành viên. Ý kiến giúp shop lựa chọn sản phẩm và cải thiện dịch vụ.','2026-10-01 08:00:00','2026-12-31 23:59:00','CLOSED'